# WRONG under `pytest -n 4`: "session" means once per WORKER, so each of the
# four workers wipes the other three workers' live sessions mid-run.
@pytest.fixture(autouse=True, scope="session")
def _reset_everything(base_url):
    httpx.post(f"{base_url}/api/testing/reset")


# RIGHT: give each worker its own data instead of resetting shared state.
@pytest.fixture(scope="session")
def worker_account(base_url, worker_id):
    username = f"qa_{worker_id}_{uuid.uuid4().hex[:8]}"
    httpx.post(
        f"{base_url}/api/auth/register",
        json={"username": username, "password": "Str0ng!Passw0rd"},
    ).raise_for_status()
    return username, "Str0ng!Passw0rd"
